hooks.command:
FILE=$(jq -r '.toolCall.args.Path // .tool_input.file_path // empty'); BASE=$(basename "$FILE"); if [ "$BASE" = ".env" ] || (printf '%s' "$BASE" | grep -qE '^\.env\.' && [ "$BASE" != ".env.example" ]); then printf '{"decision":"deny","reason":"Blocked by AGENTS.md Section 5: Reading or modifying .env files is prohibited."}
'; elif printf '%s' "$FILE" | grep -qE '(legacy-prisma-schema\.prisma|prisma\.config\.ts|src/generated/prisma/)'; then printf '{"decision":"deny","reason":"Blocked by AGENTS.md Section 8: Legacy Prisma files are read-only; use GORM in services/go-api."}
'; else printf '{"decision":"allow"}
'; fi
